// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {MyContract} from "../src/MyContract.sol";

contract InvMutTest is Test {
    MyContract c;
    function setUp() public { c = new MyContract(); }
    function testFuzz_property(address receiver, uint256 amount) public {
        vm.assume(amount > 0);
        address owner = address(this);
        vm.assume(receiver != owner);
        vm.deal(address(c), amount);
        uint256 receiverBalanceBefore = receiver.balance;
        vm.prank(owner);
        c.sendTo(receiver, amount);
        uint256 receiverBalanceAfter = receiver.balance;
        assertTrue(receiverBalanceAfter == receiverBalanceBefore + amount);
    }
}
